const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const toliara = ee.Geometry.Point([43.67, -23.35]);
  const region = toliara.buffer(10000); // 10km buffer around Toliara

  // 2. Data Acquisition & Check
  // Historical period: September 2000-2015
  const historicalStart = '2000-09-01';
  const historicalEnd = '2015-09-30';

  // Recent period: September 2021-2022
  const recentStart = '2021-09-01';
  const recentEnd = '2022-09-30';

  // Use MODIS Terra Vegetation Indices 16-Day Global 250m
  const modisCollection = 'MODIS/006/MOD13Q1';

  // Quality masking function
  function maskQuality(image) {
    const qa = image.select('SummaryQA');
    // Keep only good quality pixels (0 = good, 1 = marginal)
    const mask = qa.lte(1);
    return image.updateMask(mask).select('NDVI').multiply(0.0001); // Scale factor
  }

  // Historical collection
  const historicalCol = ee.ImageCollection(modisCollection)
    .filterBounds(region)
    .filterDate(historicalStart, historicalEnd)
    .map(maskQuality);

  const historicalSize = historicalCol.size().getInfo();
  console.log(`Historical images (2000-2015): ${historicalSize}`);

  if (historicalSize === 0) {
    console.log('No historical data found.');
    console.log('<answer>C1</answer>');
    return;
  }

  // Recent collection
  const recentCol = ee.ImageCollection(modisCollection)
    .filterBounds(region)
    .filterDate(recentStart, recentEnd)
    .map(maskQuality);

  const recentSize = recentCol.size().getInfo();
  console.log(`Recent images (2021-2022): ${recentSize}`);

  if (recentSize === 0) {
    console.log('No recent data found.');
    console.log('<answer>C1</answer>');
    return;
  }

  // 3. Processing - Calculate mean NDVI for each period
  const historicalMean = historicalCol.mean();
  const recentMean = recentCol.mean();

  // Check valid pixel counts
  const historicalCount = historicalMean.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: region,
    scale: 3000,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  const recentCount = recentMean.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: region,
    scale: 3000,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  console.log(`Historical valid pixels: ${historicalCount}`);
  console.log(`Recent valid pixels: ${recentCount}`);

  if (historicalCount === 0 || recentCount === 0) {
    console.log('No valid pixels after quality masking.');
    console.log('<answer>C2</answer>');
    return;
  }

  // 4. Calculation - Get mean NDVI values
  const historicalNDVI = historicalMean.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: region,
    scale: 3000,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  const recentNDVI = recentMean.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: region,
    scale: 3000,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  // 5. Validation & Final Answer
  console.log(`Historical NDVI (2000-2015 Sep): ${historicalNDVI?.toFixed(4)}`);
  console.log(`Recent NDVI (2021-2022 Sep): ${recentNDVI?.toFixed(4)}`);

  if (historicalNDVI === null || recentNDVI === null || 
      isNaN(historicalNDVI) || isNaN(recentNDVI) ||
      historicalNDVI < -1 || historicalNDVI > 1 ||
      recentNDVI < -1 || recentNDVI > 1) {
    console.log('Invalid NDVI calculation.');
    console.log('<answer>C3</answer>');
    return;
  }

  const change = recentNDVI - historicalNDVI;
  console.log(`NDVI Change: ${change.toFixed(4)}`);

  if (recentNDVI < historicalNDVI) {
    console.log('Vegetation greenness decreased.');
    console.log('<answer>A</answer>');
  } else {
    console.log('Vegetation greenness did not decrease.');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
